INSERT INTO public.coparent_disclosure_statutes (state_code, state_name, statute_citation, summary, confidence, source_url, updated_at)
VALUES
-- AK — Alaska [likely]
  ('AK', 'Alaska', 'Alaska Stat. § 25.20.110(e)(5) (2025)', 'In the context of a temporary custody or visitation modification order during a parent''s military deployment, the court must include a provision for ''immediate notification by each parent of a change of address or contact information to the other parent and to the court'' (§ 25.20.110(e)(5)). If a valid protective order or equivalent requires the address or contact information be kept confidential, notification is made to the court only. This is the only Alaska statute found that expressly requires address/contact notification; it is tied to military deployment temporary orders. Alaska''s general divorce custody statute (AS 25.24.150) and custody determination statute (AS 25.20.060) do not contain a universal address-notification mandate for all custody orders; notification requirements in non-deployment cases typically arise from individual court orders, not statute. Secondary sources (Alaska court forms DR-700/DR-705) require address disclosure in motion practice but that is a form rule, not a statute.', 'likely', 'https://law.justia.com/codes/alaska/title-25/chapter-20/section-25-20-110/', now()),
-- AL — Alabama [verified]
  ('AL', 'Alabama', 'Ala. Code §§ 30-3-163, 30-3-164, 30-3-165, 30-3-166 (2025) (Alabama Parent-Child Relationship Protection Act)', 'A person who has the right to establish the child''s principal residence must notify every other person entitled to custody or visitation of a proposed change of the child''s principal residence (§ 30-3-163). A person entitled to custody or visitation must notify every other such person of an intended change in their own principal residence (§ 30-3-164). Notice must be by certified mail to the last known address no later than 45 days before the change, or within 10 days after obtaining knowledge if earlier notice was not reasonably possible (§ 30-3-165(a)). The notice must include: intended new residence (specific street address), mailing address, telephone number(s), school information, date of intended change, statement of reasons, proposed revised custody/visitation schedule, and a warning that objection must be made within 30 days (§ 30-3-165(b)). Section 30-3-166 mandates that every child custody determination include prescribed notice language imposing a continuing duty to notify of any change in address or telephone number. Section 30-3-167 provides exceptions where the court finds disclosure would endanger health, safety, or liberty (domestic violence). Section 30-3-168 lists consequences for failure to provide notice.', 'verified', 'https://law.justia.com/codes/alabama/title-30/chapter-3/article-7a/section-30-3-163/', now()),
-- AR — Arkansas [verified]
  ('AR', 'Arkansas', 'Ark. Code § 9-21-106 (2025) (Uniform Deployed Parents Custody and Visitation Act)', 'An individual to whom custodial responsibility has been granted during deployment must notify the deploying parent and any other individual with custodial responsibility of any change of mailing address or residence until the grant is terminated (§ 9-21-106(a)). The individual must also provide notice to any court that has issued a custody or child support order concerning the child which is in effect. If a court order currently in effect prohibits disclosure of the address or contact information, notification may be made only to the court that issued the order, and the court shall keep the address or residence confidential (§ 9-21-106(b)). This statute is deployment-specific (Chapter 21, UPCVC Act). Arkansas does not appear to have a general, non-deployment statute requiring all parents under custody orders to disclose address changes; the duty in non-deployment cases arises from individual custody orders.', 'verified', 'https://law.justia.com/codes/arkansas/title-9/subtitle-2/chapter-21/general-provisions/section-9-21-106/', now()),
-- AZ — Arizona [verified]
  ('AZ', 'Arizona', 'Ariz. Rev. Stat. § 25-408 (2025)', 'If by written agreement or court order both parents are entitled to joint legal decision-making or parenting time and both reside in Arizona, at least 45 days'' advance written notice must be provided to the other parent before relocating the child outside the state or more than 100 miles within the state (§ 25-408(A)). Notice must be by certified mail, return receipt requested, or pursuant to Arizona rules of family law procedure (§ 25-408(B)). The court shall sanction a parent who without good cause fails to comply; sanctions affecting legal decision-making or parenting time may only be imposed consistent with the child''s best interests (§ 25-408(B)). The nonmoving parent has 30 days after notice to petition the court to prevent relocation (§ 25-408(C)). The notice must include the intended new address (including city, state, and specific physical address if known), date of intended move, specific reasons for relocation, and a proposed revised parenting plan with revised parenting time schedule and transportation arrangements (per statutory practice and court rules).', 'verified', 'https://law.justia.com/codes/arizona/title-25/section-25-408', now()),
-- CA — California [verified]
  ('CA', 'California', 'Cal. Fam. Code § 3024 (2026)', 'In making a custody order, if the court does not consider it inappropriate, the court may specify that a parent shall notify the other parent if the parent plans to change the residence of the child for more than 30 days, unless there is prior written agreement to the removal (§ 3024). The notice shall be given before the contemplated move, by mail, return receipt requested, postage prepaid, to the last known address of the parent to be notified. A copy shall also be sent to that parent''s counsel of record. To the extent feasible, notice shall be provided within a minimum of 45 days before the proposed change of residence to allow time for mediation of a new custody agreement. This section does not affect orders made before January 1, 1989. Section 3024 is permissive (''may specify'') rather than mandatory; whether the notice requirement applies depends on whether the court included it in the custody order.', 'verified', 'https://codes.findlaw.com/ca/family-code/fam-sect-3024/', now()),
-- CO — Colorado [likely]
  ('CO', 'Colorado', 'Colo. Rev. Stat. § 14-10-129 (2025)', 'A parent planning to relocate a child who resides with the relocating party a majority of the time, where the intended move would substantially change the geographical ties between the child and the other party, must provide written notice to the other parent as soon as practicable (§ 14-10-129(2)(c)). The notice must state where the parent intends to reside, the reason for the relocation, and a proposed revised parenting time plan. Colorado does not prescribe a fixed number of days for the notice; the standard is ''as soon as practicable.'' If the other parent objects, the relocating parent must file a motion with the court and bears the burden of proving the relocation is in the child''s best interests. The court evaluates nine statutory factors including reasons for the move and objection, each parent''s relationship with the child, educational opportunities, extended family, impact on the child, feasibility of a revised schedule, and any other relevant factor (§ 14-10-129(2)(c)). Colorado also has a deployment-specific notice statute at § 14-13.7-106 (mirroring the Uniform Deployed Parents Custody and Visitation Act). Note: The primary statute text for § 14-10-129 could not be directly accessed; findings rely on consistent secondary sources quoting the statute.', 'likely', 'https://law.justia.com/codes/colorado/title-14/dissolution-of-marriage-parental-responsibilities/article-10/part-1/section-14-10-129/', now()),
-- CT — Connecticut [likely]
  ('CT', 'Connecticut', 'Conn. Gen. Stat. § 46b-56d (2025)', 'In any post-judgment proceeding involving the relocation of a parent with a minor child where the relocation would have a significant impact on an existing parenting plan, the relocating parent bears the burden of proving by a preponderance of the evidence that (1) the relocation is for a legitimate purpose, (2) the proposed location is reasonable in light of that purpose, and (3) the relocation is in the best interests of the child (§ 46b-56d(a)). The court considers each parent''s reasons, quality of relationships, impact on future contact, enhancement of lives, and feasibility of preserving the relationship through suitable visitation (§ 46b-56d(b)). The statute does not itself prescribe a specific notice period or list of required disclosures; those procedural details (including a 90-day notice practice and the contents of a relocation notice) are governed by the Connecticut Practice Book and court forms (e.g., Form FM-158, Notice of Automatic Court Orders, which requires written notice of a new address within 48 hours of vacating the family residence in pending actions). The relocation statute establishes the substantive framework; the specific address/contact notification mechanics derive from court rules and standard order language rather than the statute itself.', 'likely', 'https://law.justia.com/codes/connecticut/title-46b/chapter-815j/section-46b-56d/', now()),
-- DE — Delaware [verified]
  ('DE', 'Delaware', '13 Del. Code §§ 705B, 706B, 707B, 708B (2025) (Relocation of Child or Change of Residence Address Act)', 'An individual who has the right to establish the principal residence of a child must notify every other individual entitled to custody or visitation of a proposed relocation of the child''s principal residence as required by § 707B (§ 705B). An adult individual entitled to custody or visitation must notify every other such individual of an intended change in their primary residence address as required by § 707B (§ 706B). Notice must be by first class mail to the last known address no later than the 60th day before the intended move, or the 10th day after the individual knows the required information if they did not know and could not reasonably have known it in sufficient time for 60-day notice (§ 707B(a)). The notice must include: intended new residence (specific address if known), mailing address if different, home telephone number if known, date of intended move, brief statement of reasons, proposal for revised visitation schedule, and a warning that objection must be made within 30 days or the relocation will be permitted (§ 707B(b)). Section 708B mandates that every custody or visitation order issued after the effective date include standard language imposing the notification duty on the individual, specifying the required information, the 60-day/10-day deadline, and the continuing nature of the obligation. Section 709B provides exceptions for health, safety, or liberty concerns (domestic violence). Section 734 also governs relocation factors in custody proceedings.', 'verified', 'https://delcode.delaware.gov/title13/c007/sc02/index.shtml', now()),
-- FL — Florida [verified]
  ('FL', 'Florida', 'Fla. Stat. § 61.13001 (2026) (Parental relocation with a child)', 'A parent or other person seeking relocation of a child must file a petition to relocate and serve it on the other parent and every other person entitled to access or time-sharing, unless the parties have a written agreement (§ 61.13001(3)). The petition, signed under oath under penalty of perjury, must include: a description of the intended new residence (state, city, and specific physical address if known), mailing address if different, home telephone number if known, date of intended move, a detailed statement of specific reasons for the relocation (with written job offer attached if applicable), and a proposal for revised post-relocation access/time-sharing schedule and transportation arrangements (§ 61.13001(3)(a)). The petition must include a bold statement that the other parent must file a written objection within 20 days or the relocation will be allowed without further notice or hearing (§ 61.13001(3)(a)(7)). Service must be by certified mail, restricted delivery, return receipt requested, or according to chapters 48 and 49 (§ 61.13001(3)(b)). The relocating party has a continuing duty to provide current and updated information when it becomes known (§ 61.13001(3)(c)). Relocating without complying subjects the party to contempt, return orders, and adverse factors in any custody determination (§ 61.13001(3)(e)). Relocation is defined as a change of at least 50 miles from the principal residence and for at least 60 consecutive days (§ 61.13001(1)(e)). Florida also has a deployment-specific notice statute at § 61.711.', 'verified', 'https://flsenate.gov/Laws/Statutes/2026/0061.13001', now()),
-- GA — Georgia [likely]
  ('GA', 'Georgia', 'O.C.G.A. § 19-9-1(c)(3) (2025)', 'Georgia requires a parent planning to relocate with a child under an existing custody order to provide at least 30 days'' written notice to the other parent before the intended move (§ 19-9-1(c)(3)). The notice must include the intended new address, the date of the move, the reasons for relocating, and a proposed revised parenting plan. Notice must be sent by registered mail or certified mail to the non-relocating parent''s last known address. Georgia does not impose a specific mileage threshold; the notice requirement applies to any change of residence when there is an existing custody order. Unlike many states, Georgia does not require the custodial parent to obtain court permission before relocating; the parent must provide notice, and the non-custodial parent may seek modification if the move affects the child''s welfare under § 19-9-3. Note: The full text of subsection (c)(3) could not be directly accessed from the primary source (Justia truncated the statute display); this entry relies on consistent descriptions from multiple secondary legal sources and practice guides referencing the statute.', 'likely', 'https://law.justia.com/codes/georgia/title-19/chapter-9/article-1/section-19-9-1/', now()),
-- HI — Hawaii [not found]
  ('HI', 'Hawaii', 'HRS §571-46 (no specific address-disclosure/notice-of-change statute identified)', 'Hawaii has no standalone relocation or address-change notice statute. Custody and visitation are governed by HRS §571-46 (Criteria and procedure in awarding custody and visitation; best interest of the child). The statute lists 17 factors for custody determinations and allows the court to order the address of the child and victim to be kept confidential in visitation orders involving family violence (§571-46(a)(11)(I)), but it does not mandate a specific advance-notice requirement for address changes or relocation. Relocation notice obligations in Hawaii arise from individual custody orders and parenting plans, not from a statute. A custodial parent seeking to relocate must typically provide written notice and obtain consent or court approval, but the notice period is set by the court order, not by statute.', 'not found', 'https://law.justia.com/codes/hawaii/title-31/chapter-571/section-571-46/', now()),
-- IA — Iowa [not found]
  ('IA', 'Iowa', 'Iowa Code §598.21D (Relocation of Parent as Grounds to Modify Order of Child Custody) — no notice requirement in statute', 'Iowa Code §598.21D provides that if a parent awarded joint legal custody and physical care or sole legal custody relocates the minor child''s residence to a location 150 miles or more from the residence at the time custody was awarded, the court MAY consider the relocation a substantial change in circumstances. If the court so determines, it shall modify the custody order to preserve as nearly as possible the existing relationship between the child and the nonrelocating parent. However, the statute itself does NOT contain a notice requirement — it does not mandate advance written notice to the other parent or the court. Secondary sources and relocation-notice forms reference a 60-day notice practice, but this derives from court orders, local rules, or party agreements, not from §598.21D. A pending bill (SF114) proposes adding §598.21H requiring 60 days'' advance written notice for moves outside the established school district, but this has not been confirmed as enacted law. No other Iowa statute mandating address disclosure or change-of-address notice in family-law contexts was identified.', 'not found', 'https://law.justia.com/codes/iowa/title-xv/chapter-598/section-598-21d/', now()),
-- ID — Idaho [likely]
  ('ID', 'Idaho', 'IRFL Rule 219 (Contact Information) [court rule, not statute]; Idaho Code §18-7907 (Action for Protection)', 'Idaho does not have a family-law statute mandating address disclosure or notice of change. The Idaho Rules of Family Law Procedure (IRFL) Rule 219, adopted by the Idaho Supreme Court (effective July 1, 2021), requires parties in family law actions and civil protection order actions to keep the court apprised of current mailing address, phone number, and email address, and to notify the court within 14 days of any changes. This is a court rule, not a legislative statute. Idaho Code §18-7907 (Action for Protection) requires the court clerk to forward protection orders to law enforcement within the next judicial day, but this governs law-enforcement notification, not party-to-party address disclosure between litigants.', 'likely', 'https://isc.idaho.gov/rules-procedure/irfl', now()),
-- IL — Illinois [verified]
  ('IL', 'Illinois', '750 ILCS 5/609.2 (Parent''s Relocation)', 'Illinois requires a parent intending a relocation (as defined by distance thresholds in 750 ILCS 5/600(g): >25 miles in collar counties, >50 miles elsewhere in-state, >25 miles out-of-state) to provide written notice to the other parent at least 60 days before the relocation. The notice must include: (1) the intended date of relocation, (2) the address of the intended new residence if known, and (3) the length of time the relocation will last if not indefinite. A copy must be filed with the circuit court clerk. The court may waive or seal information if there is a history of domestic violence. Failure to comply may be considered in determining good faith and can result in attorney''s fees. If the non-relocating parent signs the notice and it is filed with the court, relocation is allowed without further court action. The parenting plan or allocation judgment under 750 ILCS 5/602.10 must also include a requirement that a parent changing residence provide at least 60 days prior written notice.', 'verified', 'https://ilga.gov/legislation/ilcs/documents/075000050K609.2.htm', now()),
-- IN — Indiana [verified]
  ('IN', 'Indiana', 'IC 31-17-2.2-1 (Notice of Intent to Move Residence); IC 31-17-2.2-3 (Notice Contents); IC 31-16-9-3 (Notice of Change of Address — Support Orders)', 'Indiana has a comprehensive relocation-notice framework. IC 31-17-2.2-1 requires a relocating individual (one with custody, parenting time, or Grandparent visitation) to file a notice of intent to move with the court clerk at least 30 days before the move (or within 14 days of becoming aware if later). Exceptions apply for moves that decrease distance or increase distance by no more than 20 miles while keeping the child in the same school. IC 31-17-2.2-3 specifies notice content: intended new residence address, mailing address if different, home telephone number, other phone numbers, intended move date, brief statement of reasons, proposed revised parenting-time schedule, and a statement that objection must be filed within 60 days. Additionally, IC 31-17-2.2-2 requires parties to keep other individuals with rights to the child advised of their home address and all telephone and email addresses at all times, in writing. Separately, IC 31-16-9-3 requires any party affected by a support order to inform the clerk and state central collection unit of any change of address within 15 days after the address is changed.', 'verified', 'https://law.justia.com/codes/indiana/title-31/article-17/chapter-2-2/section-31-17-2-2-1/', now()),
-- KS — Kansas [verified]
  ('KS', 'Kansas', 'KSA 23-3222 (Change in Child''s Residence; Notice; Effect; Exceptions)', 'Kansasstatute requires a parent entitled to legal custody or residency of or parenting time with a child to give written notice to the other parent not less than 30 days prior to: (1) changing the residence of the child, or (2) removing the child from the state for a period exceeding 90 days. Notice must be sent by restricted mail, return receipt requested, to the last known address of the other parent. Failure to give notice is indirect civil contempt punishable as provided by law, and the court may assess reasonable attorney fees and other expenses incurred by the other parent. A change of residence or removal may be considered a material change of circumstances justifying modification of a prior order. Exceptions apply when the other parent has been convicted of certain crimes (article 34, 35, or 36 of KSA chapter 21, or specific domestic-violence-related statutes) in which the child is the victim. History: L. 1984, ch. 213, §1; amended multiple times through 2015.', 'verified', 'https://www.ksrevisor.gov/statutes/chapters/ch23/023_032_0022.html', now()),
-- KY — Kentucky [not found]
  ('KY', 'Kentucky', 'KRS 403.340 (Modification of Custody Decree) — no relocation-notice provision; FCRPP Rule 7(2) (Relocation) [court rule, not statute]', 'Kentucky does not have a statute requiring address disclosure or notice of change in family-law contexts. KRS 403.340 governs modification of custody decrees (standards, timing, best-interest factors) but does not contain a relocation-notice provision — the subsection cited in some secondary sources as containing ''formal notice of intent to relocate'' (KRS 403.340(5)) actually addresses the presumption of joint custody, not notice. The relocation-notice requirement in Kentucky comes from FCRPP Rule 7(2) (Family Court Rules of Procedure and Practice), a court rule adopted by the Kentucky Supreme Court, not a legislative statute. FCRPP 7(2) requires: (a) joint custodians to file written notice with the court and serve the non-relocating joint custodian before relocating, including the proposed relocation address, date, and effect on time-sharing; (b) sole custodians to do the same with the non-custodial parent. The non-relocating party has 20 days to file a motion to modify. KRS 403.770 addresses address confidentiality for domestic-violence petitioners but does not impose a general address-disclosure obligation.', 'not found', 'https://law.justia.com/codes/kentucky/2025/chapter-403/section-403-340/', now()),
-- LA — Louisiana [verified]
  ('LA', 'Louisiana', 'La. R.S. 9:355.5 (Mailing Notice of Proposed Relocation Address)', 'Louisiana requires notice of a proposed relocation of the principal residence of a child to be given by registered or certified mail, return receipt requested, or delivered by commercial courier, to the last known address of the person entitled to notice no later than: (1) the 60th day before the proposed relocation, or (2) the 10th day after the person proposing relocation knows the required information, if 60-day notice was not reasonably possible. The notice must include: (1) current mailing address of the person proposing relocation, (2) intended new residence including specific physical address if known, (3) intended new mailing address if different, (4) home and cellular telephone numbers if known, (5) date of proposed relocation, (6) brief statement of specific reasons, (7) proposal for revised schedule of physical custody or visitation, and (8) a statement that the person entitled to object must object in writing by registered or certified mail within 30 days of receipt and should seek legal advice immediately. A person required to give notice has a continuing duty to provide the information as it becomes known. Relocation is defined (RS 9:355.1) as a change in the principal residence of a child for 60 days or more.', 'verified', 'https://law.justia.com/codes/louisiana/revised-statutes/title-9/rs-9-355-5/', now()),
-- MA — Massachusetts [verified]
  ('MA', 'Massachusetts', 'M.G.L. c. 208, § 30 (Removal of children from the Commonwealth); M.G.L. c. 208, § 31 (custody definitions and shared custody framework)', 'Massachusetts requires a parent subject to a custody or visitation order to obtain either the other parent''s written consent or a court order before permanently removing a child from the Commonwealth. The removal statute (§ 30) applies when the child was born in MA or has resided there at least 5 years and a custody/visitation order is in place or pending. Courts apply a two-step analysis: (1) ''real advantage'' test when one parent has primary physical custody — the moving parent must show a genuine, material benefit to the relocation; (2) ''best interests of the child'' test when custody is shared or nearly equal. M.G.L. c. 208, § 31 defines sole/shared legal and physical custody and establishes that parental rights are held equal absent misconduct, with the child''s happiness and welfare controlling. Section 31 also addresses disclosure of records including address restrictions where safety warrants.', 'verified', 'https://malegislature.gov/Laws/GeneralLaws/PartII/TitleIII/Chapter208/Section30', now()),
-- MD — Maryland [verified]
  ('MD', 'Maryland', 'Md. Family Law §9-106 (Relocation Notice)', 'Maryland law provides that in any custody or visitation proceeding, the court may include as a condition of a custody or visitation order a requirement that either party provide advance written notice of at least 90 days to the court, the other party, or both, of the intent to relocate the permanent residence of the party or the child either within or outside the State. The court may prescribe the form and content of the notice. If the court orders notice to the other party, mailing by certified mail, return receipt requested, to the last known address is deemed sufficient. If a party files a petition regarding a proposed relocation within 20 days of the notice, the court shall set a hearing on an expedited basis. If the relocation would significantly interfere with the other parent''s ability to maintain the predetermined parenting time schedule, the court shall also set an expedited hearing. The court may waive the notice requirement on a showing that notice would expose the child or either party to abuse (as defined in FL §4-501) or for other good cause. If relocation is required in less than 90 days, the court may consider as a defense that relocation was necessary due to financial or other extenuating circumstances and notice was given within a reasonable time. The court may consider any violation of the notice requirement as a factor in subsequent custody or visitation proceedings.', 'verified', 'https://mgaleg.maryland.gov/mgawebsite/Laws/StatuteText?article=gfl&section=9-106', now()),
-- ME — Maine [verified]
  ('ME', 'Maine', '19-A M.R.S. §1653(14) (Parental Rights and Responsibilities — Notice of Relocation)', 'Maine law requires that at least 30 days before the intended relocation of a child by a parent, the parent shall provide notice to the other parent of the intended relocation. If the relocation must occur in fewer than 30 days, the relocating parent shall provide notice as soon as possible. If the parent believes notifying the other parent will cause danger to the relocating parent or the child, the parent shall notify the court instead, and the court shall provide appropriate notice to the other parent in a manner determined to provide safety. The notice shall include the address and, if known, the telephone number of the residence where the parent intends to relocate the child. Maine uses the term ''parental rights and responsibilities'' rather than ''custody.'' The statute is part of the primary custody-determination section (§1653), and the relocation-notice provision is subsection (14). After receiving notice, the non-relocating parent may object in court or seek a change in custody.', 'verified', 'https://legislature.maine.gov/statutes/19-a/title19-Asec1653.html', now()),
-- MI — Michigan [verified]
  ('MI', 'Michigan', 'MCL 722.31 (Child Custody Act of 1970, § 11 — Legal residence change of child whose parental custody governed by court order)', 'Michigan prohibits a parent from changing a child''s legal residence to a location more than 100 miles from the child''s legal residence at the time the custody action commenced, unless the other parent consents or the court permits the change after considering five factors (quality of life improvement, compliance with prior parenting time orders, feasibility of modifying parenting time, whether the opposition is motivated by financial advantage, and domestic violence). Every custody/parenting time order must include a provision stating the parents'' agreement on how a change in the child''s legal residence will be handled; if no agreement, the order must include a statutory default prohibition. The restriction does not apply if sole legal custody is granted to one parent, if the residences were already more than 100 miles apart at the outset, or if the change brings the residences closer together.', 'verified', 'https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-722-31', now()),
-- MN — Minnesota [verified]
  ('MN', 'Minnesota', 'Minn. Stat. § 518.175, Subd. 3 (Move to another state); Subd. 5 (Modification of parenting plan or order for parenting time)', 'Minnesota prohibits the parent with whom the child resides from moving the child''s residence to another state without a court order or the other parent''s consent, if the other parent has been given parenting time by the decree. A move intended to interfere with the other parent''s parenting time shall not be permitted. The court applies a best-interests standard with eight enumerated factors: the nature/quality/extent of the child''s relationship with each parent and significant persons; the child''s age, developmental stage, needs, and likely impact of relocation; feasibility of preserving the relationship through suitable parenting time arrangements; the child''s preference (considering age/maturity); established pattern of conduct to promote or thwart the relationship; whether relocation enhances quality of life for custodial parent and child; reasons of each person for seeking or opposing; and the effect of domestic abuse on safety and welfare. Burden of proof is on the parent requesting the move, except when that parent is a victim of domestic abuse by the other parent (burden shifts). Subd. 5 governs modification of parenting plans and orders for parenting time.', 'verified', 'https://www.revisor.mn.gov/statutes/cite/518.175', now()),
-- MO — Missouri [verified]
  ('MO', 'Missouri', 'RSMo § 452.377 (Relocation of child by parent for more than ninety days — required procedure — violation, effect — notice of relocation of parent, required procedure)', 'Missouri requires written notice by certified mail, return receipt requested, to any party with custody or visitation rights at least 60 days in advance of a proposed relocation of a child''s principal residence for 90 days or more (absent exigent circumstances). The notice must include: (1) intended new residence including specific address and mailing address (or city if unknown); (2) home telephone number if known; (3) date of intended move; (4) brief statement of specific reasons; (5) proposal for revised custody/visitation schedule; and (6) notice of the other parent''s right to file a motion to prevent relocation with an accompanying affidavit within 30 days of receipt. Every court order establishing or modifying custody or visitation after August 28, 1998 must include a prescribed statutory notice language. Failure to provide notice is a factor in custody modification, a basis for ordering return of the child, and sufficient cause to order payment of reasonable expenses and attorney fees. The relocating parent bears the burden of proving good faith and best interests of the child. Address confidentiality program participants are exempt from disclosing specific address but may be required to submit under seal for in camera review.', 'verified', 'https://revisor.mo.gov/main/OneSection.aspx?section=452.377', now()),
-- MS — Mississippi [not found]
  ('MS', 'Mississippi', 'Miss. Code Ann. § 93-5-24 (custody generally); address-notification requirement via Miss. Unif. Ch. Ct. Rules, Rule 8.06 (not a standalone statute)', 'Mississippi does not have a standalone statutory provision requiring advance notice of address change to a co-parent before relocation with a child. The Mississippi Uniform Chancery Court Rule 8.06 provides that all custody orders should require parents to keep each other informed of their address and telephone number and to notify the court and the other parent of a new address within five days after moving. This rule is intended to prevent one parent from hiding a child''s whereabouts from the other, but does not function as a relocation-permission mechanism — it is a post-move notification requirement. Mississippi custody law was substantially revised effective July 1, 2026 (HB 1662), creating a rebuttable presumption in favor of joint custody with equal parenting time under § 93-5-24, but the relocation-notice gap remains. No statutory notice-of-relocation provision comparable to other states was located in the Mississippi Code or its session laws as of the research date.', 'not found', 'https://www.womenslaw.org/laws/ms/custody/all', now()),
-- MT — Montana [verified]
  ('MT', 'Montana', 'MCA § 40-4-217 (Notice of intent to move); MCA § 40-4-204 (parenting plan update requirements); MCA § 40-4-219 (motion for amendment of residential schedule)', 'Montana requires a parent who intends to change residence to provide written notice to the other parent. If the change in residence will significantly affect the child''s contact with the other parent, the parent must file a motion for amendment of the residential schedule and a proposed revised residential schedule with the court that adopted the schedule, served personally or by certified mail not less than 30 days before the proposed change. The notice must contain a specific warning statement that the relocation may be permitted and the proposed revised schedule may be ordered without further proceedings unless a response and alternate revised schedule are filed within 21 days. The parent receiving service has 21 days to file a response; failure to respond within that period constitutes acceptance of the proposed revised residential schedule. A person entitled to object may file regardless of whether proper notice was received. Parenting plans under § 40-4-204 must include a provision requiring both parties to update the court with changes to certain information.', 'verified', 'https://mca.legmt.gov/bills/mca/title_0400/chapter_0040/part_0020/section_0170/0400-0040-0020-0170.html', now()),
-- NC — North Carolina [verified]
  ('NC', 'North Carolina', 'N.C. Gen. Stat. § 50A-354 (2023)', 'Under the Uniform Deployed Parents Custody and Visitation Act, a deploying parent shall, in a record, notify the other parent of a pending deployment not later than seven days after receiving notice of deployment unless reasonably prevented by the circumstances of service. Each parent shall provide the other parent, in a record, with a plan for fulfilling that parent''s share of custodial responsibility during deployment as soon as reasonably possible after receiving notice of deployment. If an existing court order prohibits disclosure of the address or contact information of the other parent, notification may be made only to the issuing court, which shall forward it to the other parent and keep the address confidential. Notice is not required if parents live in the same residence and have actual notice.', 'verified', 'https://codes.findlaw.com/nc/chapter-50a-uniform-child-custody-jurisdiction-and-enforcement-act-and-uniform-deployed-parents-custody-and-visitation-act/nc-gen-st-sect-50a-354/', now()),
-- ND — North Dakota [verified]
  ('ND', 'North Dakota', 'N.D. Cent. Code § 14-09.3-04 (2024)', 'Under the Uniform Deployed Parents Custody and Visitation Act, a deploying parent shall notify in a record the other parent of a pending deployment or redeployment not later than seven days after receiving notice unless reasonably prevented by the circumstances of service. Each parent shall provide in a record the other parent with a plan for fulfilling that parent''s share of custodial responsibility during deployment as soon as reasonably possible after notification. If a court order currently in effect prohibits disclosure of the address or contact information of the other parent, notification may be made only to the issuing court, which shall forward it to the other parent and keep the address confidential. Notification is not required if parents live in the same residence and both have actual notice of the deployment.', 'verified', 'https://codes.findlaw.com/nd/title-14-domestic-relations-and-persons/nd-cent-code-sect-14-09-3-04/', now()),
-- NE — Nebraska [verified]
  ('NE', 'Nebraska', 'Neb. Rev. Stat. § 43-2929(2) (Parenting plan; contents — duty to notify of change of address); Neb. Rev. Stat. § 43-4606 (Duty to notify of change of address — deployment context); Neb. Rev. Stat. § 42-364 (custody, parenting time, and dissolution actions)', 'Under Nebraska''s Parenting Act, every parenting plan approved by the court shall require that the parties notify each other of a change of address. The address or return address shall only include the county and state for a party who is living or moving to an undisclosed location because of safety concerns. This is the primary statutory mechanism for co-parent address disclosure. Separately, § 43-4606 imposes a duty on an individual granted custodial responsibility during a parent''s deployment (under the Uniform Deployed Parents Custody and Visitation Act, §§ 43-4608 to 43-4623) to notify the deploying parent and any other person with custodial responsibility of any change of mailing address or residence until the grant is terminated, and to provide notice to any court that has issued a custody or child support order. Section 42-364 governs dissolution actions involving child custody, parenting time, and visitation and requires a parenting plan under the Parenting Act.', 'verified', 'https://nebraskalegislature.gov/laws/statutes.php?statute=43-2929', now()),
-- NH — New Hampshire [verified]
  ('NH', 'New Hampshire', 'RSA 461-A:12 (Relocation of a Residence of a Child)', 'New Hampshire''s relocation statute applies any time after the filing of a parenting petition or divorce petition, and applies to any residence in which the child resides at least 150 days a year. It does not apply if the relocation results in the residence being closer to the other parent or within the child''s current school district. A parent shall not relocate a child without a court order unless relocation is necessary to protect the safety of the parent or child. Prior to relocating, the parent must provide reasonable notice to the other parent — 60 days notice is presumed reasonable unless other factors justify shorter notice (e.g., safety protection, abode unavailable due to circumstances beyond the parent''s control). At the request of either parent, the court shall hold a hearing; the court must hold an evidentiary hearing within 30 days of the request. The parent seeking relocation bears the initial burden of demonstrating by a preponderance of the evidence that the relocation is for a legitimate purpose and the proposed location is reasonable in light of that purpose. If that burden is met, the burden shifts to the other parent to prove the relocation is not in the child''s best interests.', 'verified', 'https://law.justia.com/codes/new-hampshire/2023/title-xliii/chapter-461-a/section-461-a-12/', now()),
-- NJ — New Jersey [verified]
  ('NJ', 'New Jersey', 'N.J.S.A. 9:2-2 (Custody of children of divorced or separated parents within jurisdiction of Superior Court; removal from jurisdiction; consent; security)', 'New Jersey''s removal statute provides that when the Superior Court has jurisdiction over custody and maintenance of minor children of divorced, separated, or living-separate parents, and such children are natives of New Jersey or have resided five years within its limits, they shall not be removed out of its jurisdiction against their own consent (if of suitable age to signify the same) nor while under that age without the consent of both parents, unless the court, upon cause shown, shall otherwise order. The court may, upon application of any person on behalf of such minors, require security and issue writs and processes as deemed proper. N.J.S.A. 9:2-2 is the governing removal statute; case law over the last 13+ years has defined the factors courts consider in removal disputes. Even intra-state relocation may require notice under the applicable parenting plan or court order. This is a removal-from-jurisdiction statute rather than a pure address-notification statute, but it functions as the primary mechanism for co-parent notice of out-of-state moves.', 'verified', 'https://law.justia.com/codes/new-jersey/title-9/section-9-2-2/', now()),
-- NM — New Mexico [verified]
  ('NM', 'New Mexico', 'N.M. Stat. § 40-4-9.1(J)(4) (2025)', 'In joint custody proceedings, if either parent plans to change his/her home city or state of residence, the parent must provide the other parent thirty (30) days'' written notice stating the date, city, and state of the intended new residence, the reasons for the change, a proposal for a revised parenting plan, and a statement that the other parent may file a motion for modification of the custody or parenting plan order. The statute applies to any proceeding in which joint custody is at issue. The notice requirement is incorporated into the parenting plan approved by the court.', 'verified', 'https://law.justia.com/codes/new-mexico/chapter-40/article-4/section-40-4-9-1/', now()),
-- NV — Nevada [verified]
  ('NV', 'Nevada', 'NRS 125C.006 (Consent required from noncustodial parent to relocate child when primary physical custody established; petition for permission from court; attorney''s fees and costs); NRS 125C.0065 (joint physical custody relocation); NRS 125C.0645 (Duty to notify of change of address — Uniform Deployed Parents Custody and Visitation Act)', 'Nevada requires that when primary physical custody has been established by court order and the custodial parent intends to relocate the residence outside the state or to a place within the state at such a distance that would substantially impair the other parent''s ability to maintain a meaningful relationship with the child, the custodial parent must, before relocating: (a) attempt to obtain the written consent of the noncustodial parent; and (b) if consent is refused, petition the court for permission to relocate with the child. Attorney''s fees and costs may be awarded to the custodial parent if the noncustodial parent refused consent without reasonable grounds or for harassment. A parent who relocates without consent or court permission is subject to NRS 200.359 (unlawful relocation). NRS 125C.0065 provides the parallel procedure for joint physical custody situations (relocating parent must obtain non-relocating parent''s consent or petition for primary physical custody). NRS 125C.0645 imposes a duty under the Uniform Deployed Parents Custody and Visitation Act for a non-deploying parent or person with custodial responsibility to notify the deploying parent of any change of mailing address or residence.', 'verified', 'https://www.leg.state.nv.us/nrs/nrs-125c.html', now()),
-- NY — New York [verified]
  ('NY', 'New York', 'N.Y. Dom. Rel. Law § 76-h (2025)', 'In any child custody proceeding, each party must, in its first pleading or attached affidavit, provide under oath the child''s present address or whereabouts, the places where the child has lived during the last five years, and the names and present addresses of persons with whom the child has lived during that period. Each party has a continuing duty to inform the court of any proceeding in this or any other state that could affect the current proceeding. Subdivision 5 permits the court to order that a party''s or child''s address not be disclosed in pleadings upon a finding that disclosure would unreasonably risk health or safety (e.g., domestic violence). The party whose address is kept confidential must inform the court clerk of any change in address for service of process.', 'verified', 'https://www.nysenate.gov/legislation/laws/DOM/76-H', now()),
-- OH — Ohio [verified]
  ('OH', 'Ohio', 'Ohio Rev. Code § 3109.051(G) (2023); Ohio Rev. Code § 3127.23 (Parenting Proceeding Affidavit)', 'Under R.C. 3109.051(G)(1), if the residential parent intends to move to a residence other than the residence specified in the parenting time order or decree, the parent shall file a notice of intent to relocate with the court that issued the order. The court shall send a copy of the notice to the non-residential parent and may schedule a hearing to determine whether to revise the parenting time schedule. Under R.C. 3127.23, in any parenting proceeding each party must provide in the first pleading or by affidavit: the child''s present address and places where the child lived within the last five years; the name and present address of each person with whom the child lived during that period; information about other parenting proceedings; and the name of any person not a party who has physical custody or claims visitation rights. If health/safety would be jeopardized by disclosure, the information is sealed.', 'verified', 'https://codes.ohio.gov/ohio-revised-code/section-3109.051', now()),
-- OK — Oklahoma [verified]
  ('OK', 'Oklahoma', '43 Okl. Stat. § 112.3 (2025)', 'A person who has the right to establish the principal residence of a child shall notify every other person entitled to visitation of a proposed relocation of the child''s principal residence. An adult entitled to visitation shall notify every other person entitled to custody or visitation of an intended change in the adult''s primary residence address. Notice must be given by mail to the last-known address no later than 60 days before the intended move (or 10 days after learning of the change if the person did not know and could not reasonably have known in time). Notice must include: the intended new residence address, mailing address, home telephone number, date of the move, reasons for relocation, a revised visitation schedule proposal, and a warning that objection must be made within 30 days or relocation is permitted. Court orders must include a mandatory notice provision. The obligation to provide updated information continues as long as custody or visitation rights exist.', 'verified', 'https://law.justia.com/codes/oklahoma/title-43/section-43-112-3', now()),
-- OR — Oregon [verified]
  ('OR', 'Oregon', 'Or. Rev. Stat. § 107.159 (2025); Or. Rev. Stat. § 107.164 (2025)', 'ORS 107.159: In any court order or judgment granting custody and parenting time/visitation (except protective orders under ORS 107.700-107.735), the court shall include a provision requiring that neither parent may move to a residence more than 60 miles further distant from the other parent without giving the other parent reasonable notice of the change of residence and providing a copy of the notice to the court. A parent is not required to give notice if the court, upon ex parte motion and for good cause, suspends the requirement. ORS 107.164: Unless otherwise ordered by the court, both parents have a continuing responsibility, once a custody or protective order is issued, to provide addresses and contact telephone numbers to the other parent and to immediately notify the other parent of any emergency circumstances or substantial changes in the child''s health.', 'verified', 'https://oregon.public.law/statutes/ors_107.159', now()),
-- PA — Pennsylvania [verified]
  ('PA', 'Pennsylvania', '23 Pa. Cons. Stat. § 5337 (2025); 51 Pa. Cons. Stat. § 4605(c) (2025)', '23 Pa.C.S. § 5337 (Relocation): No relocation shall occur unless every individual with custody rights consents or the court approves. The party proposing relocation must notify every other individual with custody rights by certified mail, return receipt requested, no later than the 60th day before the proposed relocation (or the 10th day after learning of it if the party did not know and could not reasonably have known). Notice must include: the intended new residence address, mailing address, names/ages of individuals in the new residence, home telephone number, new school district/school, date of relocation, reasons for relocation, a proposal for revised custody schedule, and a warning that objection within 30 days forecloses the right to object. If information is later discovered, the party must promptly inform all recipients. 51 Pa.C.S. § 4605(c): During deployment-related custodial responsibility, an individual who proposes to change the child''s residence must comply with 23 Pa.C.S. § 5337. An individual granted custodial responsibility during deployment must notify the deploying parent and any other individual with custodial responsibility of a change of mailing address in a record, continuing until the grant is terminated.', 'verified', 'https://palegis.us/statutes/consolidated/view-statute?55=&chpt=53&div=00.&iFrame=true&sctn=37&subsctn=0&ttl=23&txtType=HTM', now()),
-- RI — Rhode Island [verified]
  ('RI', 'Rhode Island', 'R.I. Gen. Laws § 15-20-4 (2025); R.I. Gen. Laws § 15-8-28 (2025); R.I. Gen. Laws § 15-5-14.1(h) (2025)', 'R.I. Gen. Laws § 15-20-4: In all child support cases under the Rhode Island state plan (IV-D of the Social Security Act), when the obligor parent and/or custodial parent change residence, it is the duty of that parent to notify the department of the change of residence within ten (10) days. R.I. Gen. Laws § 15-8-28 (Uniform Law on Paternity): During the pendency of paternity proceedings and throughout the duration of the child support order, parents must notify the department of any change in address, phone number, or place of employment within ten (10) days. R.I. Gen. Laws § 15-5-14.1(h) (Automatic Orders in Divorce): If the parties share a child or children, a party vacating the family residence shall notify the other party or the other party''s attorney, in writing, within forty-eight (48) hours of such move, of an address where the relocated party can receive communication. This does not apply if there is a prior contradictory court order.', 'verified', 'https://webserver.rilegislature.gov/Statutes/TITLE15/15-20/15-20-4.htm', now()),
-- SC — South Carolina [verified]
  ('SC', 'South Carolina', 'S.C. Code Ann. § 63-15-510 (2025)', 'An individual to whom custodial responsibility has been assigned or granted during deployment pursuant to Subarticle 2 or 3 of the Uniform Deployed Parents Custody and Visitation Act shall notify the deploying parent and any other individual with custodial responsibility of any change of mailing address or residence until the assignment or grant is terminated. The individual shall provide the notice to any court that has issued an existing custody or child support order concerning the child. If an existing court order prohibits disclosure of the address or contact information of the individual, notification may be made only to the court that issued the order. The court shall keep confidential the mailing address or residence of the individual. Enacted by 2015 Act No. 61 (H.3156), Section 1, effective June 4, 2015.', 'verified', 'https://law.justia.com/codes/south-carolina/title-63/chapter-15/section-63-15-510', now()),
-- SD — South Dakota [verified]
  ('SD', 'South Dakota', 'SDCL 25-5-7.3; SDCL 25-4A-A Appendix A § 1.1 (South Dakota Parenting Guidelines)', 'SDCL 25-5-7.3 requires both parents to have equal access to child records (medical, dental, school) and mandates that ''the parents shall make reasonable efforts to ensure that the name and address of the other parent is listed on all such records.'' SDCL 25-4A-A (South Dakota Parenting Guidelines, which become mandatory as a court-ordered parenting plan when parents cannot agree, per SDCL 25-4A-11) provides in Guideline 1.1: ''Parents must always keep each other advised of their home and work addresses and telephone numbers.'' SDCL 25-5-7.4 further requires that when enrolling a child in any activity requiring a written application, the enrolling parent must provide the other parent''s name and address. South Dakota has no separate generic relocation-notice statute for custody cases outside these guidelines; the parenting guidelines carry the force of court order. No standalone statute comparable to other states'' relocation-notification laws was found.', 'verified', 'https://sdlegislature.gov/Statutes/Codified_Laws/DisplayStatute.aspx?Statute=25-5-7.3', now()),
-- TN — Tennessee [verified]
  ('TN', 'Tennessee', 'Tenn. Code Ann. § 36-6-108 (Parental relocation)', 'After custody or co-parenting has been established by a permanent parenting plan or final order, if a parent spending intervals of time with a child desires to relocate outside the state or more than 50 miles from the other parent within the state, the relocating parent shall send a notice to the other parent at the other parent''s last known address by registered or certified mail, not later than 60 days prior to the move (unless excused by the court for exigent circumstances). The notice must contain: (1) statement of intent to move; (2) location of proposed new residence; (3) reasons for proposed relocation; and (4) statement that absent agreement or objection by the nonrelocating parent within 30 days, the relocating parent will be permitted to do so by law. Absent agreement or timely objection, the relocating parent must file a petition seeking approval. The nonrelocating parent has 30 days to respond in opposition. The court determines relocation based on best-interest factors under § 36-6-106(a). No standalone initial-disclosure statute requiring parents to share contact info at the outset of a parenting plan was found; the relocation statute (§ 36-6-108) is the primary address-disclosure/notice mechanism.', 'verified', 'https://law.justia.com/codes/tennessee/title-36/chapter-6/part-1/section-36-6-108/', now()),
-- TX — Texas [verified]
  ('TX', 'Texas', 'Tex. Fam. Code § 105.006 (Contents of final order – notice of change of information); Tex. Fam. Code § 153.076 (Notice of change of residence)', 'Texas Family Code § 105.006(a) requires every final custody/SAPCR order to contain each party''s current residence address, mailing address, email address, home telephone number, name of employer, address of employment, and work telephone number. Subsection (b) orders each party to inform every other party, the court, and the state case registry of any intended change in that information, at the earlier of 60 days before the change or 5 days after the party learns of the change. § 105.006(d) requires a boldfaced warning in the order that failure to obey can result in contempt (up to 6 months jail, $500 fine per violation, attorney''s fees). § 153.076 separately requires that when a sole managing conservator or possessory conservator intends to change the residence of the child to a different county or more than 100 miles from the other conservator (within or outside Texas), the conservator must provide written notice to the other conservator at least 60 days before the move, including the new address. This applies unless a geographic restriction is already in place or the other conservator has actual notice. The court may waive the notice requirement for good cause.', 'verified', 'https://statutes.capitol.texas.gov/Docs/FA/htm/FA.105.htm', now()),
-- UT — Utah [verified]
  ('UT', 'Utah', 'Utah Code § 81-9-209 (Notice of relocation – formerly Utah Code § 30-3-37, recodified effective Sept. 1, 2024); Utah Code § 81-9-201 et seq. (parent-time provisions, formerly Title 30, Chapter 3)', 'Utah Code § 81-9-209 defines ''relocation'' as moving 150 miles or more from the residence of the other parent. The relocating parent shall provide written notice to the other parent at least 60 days before the intended relocation. The notice must contain statements affirming: (a) the parent-time provisions in Subsection (9) or a parent-time schedule approved by both parties will be followed; and (b) that a parent will not interfere with the other''s parental rights pursuant to court-ordered parent-time arrangements. Upon motion of any party or the court''s own motion, the court shall schedule a hearing to review the relocation and make appropriate orders regarding parent-time and transportation costs. If relocation is not in the best interest of the child and the parent relocates anyway, the court may order a change of custody. Utah''s 2024 statutory reorganization moved domestic relations provisions from Title 30 to Title 81; older cases and orders may cite the former § 30-3-37. No standalone statute requiring initial address disclosure at the time a parenting plan is first established was found separate from the relocation framework.', 'verified', 'https://le.utah.gov/xcode/Title81/Chapter9/81-9-S209.html', now()),
-- VA — Virginia [verified]
  ('VA', 'Virginia', 'Va. Code Ann. § 20-124.5 (Notification of relocation)', 'Virginia Code § 20-124.5 requires that in any proceeding involving custody or visitation, the court shall include as a condition of any custody or visitation order a requirement that 30 days'' advance written notice be given to the court and the other party by any party intending to relocate and of any intended change of address, unless the court, for good cause shown, orders otherwise. The court may require the notice be in such form and contain such information as it deems proper and necessary. Virginia does not set a minimum distance threshold — any change of address triggers the notice. The court has broad discretion over form and content. The statute does not itself list specific required data fields (new address, phone, etc.); those are typically specified in the individual court order. Virginia also maintains a separate Address Confidentiality Program (Va. Code § 2.2-515.2) for domestic violence victims, which can interact with the relocation notice requirement via a ''good cause'' waiver. No standalone initial-disclosure statute requiring parties to provide contact info at the outset of a custody case was found outside the § 105.006-type content-of-order requirement (Virginia''s equivalent is more casually handled through local rules and the custody order itself).', 'verified', 'https://law.lis.virginia.gov/vacode/title20/chapter12/section20-124.5/', now()),
-- VT — Vermont [verified]
  ('VT', 'Vermont', '15 V.S.A. § 666 (Parenting plan contents); 15 V.S.A. § 664 (Definitions: legal responsibility, physical responsibility, parent-child contact); Vermont Parenting Plan form req. § 3.1(c) (both parents shall maintain current contact information and notify the other within 7 days of any change)', '15 V.S.A. § 666 governs parenting plans in Vermont (the state uses ''parental rights and responsibilities'' rather than custody). A parenting plan approved by the court must address, among other things, legal and physical responsibility, parent-child contact, communication between parents, and dispute resolution. The Vermont Judiciary standard parenting plan form (required for stipulated agreements, filed as Form 400-00825) includes in Section 3.1(c) a contractual requirement that both parents shall maintain current contact information (address, phone, email, emergency contacts) and notify the other parent within 7 days of any change. Section 8.1 of the form (Relocation) requires the custodial parent to give at least 60 days'' written notice before relocating within Vermont (including new address, reason, and proposed modified schedule); out-of-state relocation requires either written consent of the other parent or court approval. The 7-day contact-info update duty and the 60-day relocation notice are embedded in the court-approved plan form rather than a standalone statute section; the statutory anchor is 15 V.S.A. § 666 (parenting plan approval) read with § 665(b) (best interests). No separate statute with a bright-line standalone relocation-notice requirement akin to other states'' statutes was found — the obligation flows from the plan form approved under § 666.', 'verified', 'https://legislature.vermont.gov/statutes/section/15/021/01152', now()),
-- WA — Washington [verified]
  ('WA', 'Washington', 'RCW 26.09.430 (Notice requirement); RCW 26.09.440 (Notice contents and delivery); RCW 26.09.405–.560 (Child Relocation Act)', 'RCW 26.09.430 requires any person with whom the child resides a majority of the time, or a person with substantially equal residential time (45% or more, per RCW 26.09.525), to notify every other person entitled to residential time or visitation under a court order if that person intends to relocate. For a move outside the child''s current school district, RCW 26.09.440 requires notice by personal service or mail with return receipt, no less than 60 days before the relocation (or within 5 days of learning the information if the person did not know and could not reasonably have known earlier, and it''s not reasonable to delay). The notice must include: (i) an address for service of process during the objection period; (ii) a brief statement of specific reasons for relocation; (iii) a bold all-caps warning that the relocation will be permitted unless an objection is filed within 30 days; (iv) the specific street address (or city/state if unknown); (v) new mailing address if different; (vi) new home phone number; (vii) name/address of new school and daycare if applicable; (viii) the intended relocation date; and (ix) a proposed revised parenting plan. The relocating parent has a continuing duty to promptly update information as it becomes known. RCW 26.09.450 provides that a move within the same school district cannot be objected to under the relocation chapter, though the other parent can still seek modification under RCW 26.09.260. RCW 26.09.460 provides a safety exception for domestic violence shelter residents (up to 21-day delay). No separate statute requiring initial address/contact disclosure at the time of first establishing a parenting plan (outside the relocation framework) was found — the relocation act is the primary mechanism.', 'verified', 'https://app.leg.wa.gov/rcw/default.aspx?cite=26.09.440', now()),
-- WI — Wisconsin [verified]
  ('WI', 'Wisconsin', 'Wis. Stat. § 767.41(6)(h) (Information in custody/placement orders – notice of address); Wis. Stat. § 767.481 (Relocating a child''s residence); Wis. Stat. § 767.14 (Change of address – clerk''s duty)', 'Wis. Stat. § 767.41(6)(h), created by 2017 Wisconsin Act 203, requires that in making an order of legal custody and periods of physical placement, the court shall in writing inform the parents (and any other person granted legal custody) of: (1) that each parent must notify the other parent, the child support agency, and the clerk of court of the address at which they may be served within 10 business days of moving to that address (street or post office address); (2) that the address provided to the court is the address on which the other parties may rely for service of any motion relating to modification of custody/placement or to relocating the child''s residence; and (3) that a parent granted periods of physical placement must obtain a court order before relocating with the child 100 miles or more from the other parent (if the other parent also has court-ordered periods of physical placement). Wis. Stat. § 767.481 governs relocation: if one parent intends to relocate and reside with the child 100 miles or more from the other parent, the relocating parent must file a motion with the court seeking permission, including a relocation plan (date, municipality/state of new residence, reason, proposed new placement schedule, transportation costs), and serve the other parent by mail. The other parent must file an objection no later than 5 days before the initial hearing. § 767.14 requires the circuit court clerk, within 5 business days of receiving notice of an address change by a party to an action affecting the family, to enter the new address in the case file. The 10-business-day contact-address notification duty under § 767.41(6)(h)1 is the general address-disclosure requirement applicable to all custody/placement orders.', 'verified', 'https://docs.legis.wisconsin.gov/document/statutes/767.41', now()),
-- WV — West Virginia [verified]
  ('WV', 'West Virginia', 'W. Va. Code § 48-31-106 (Duty to notify of change of address — Uniform Deployed Parents Custody and Visitation Act); W. Va. Code § 48-31-105 (Notification required of deploying parent)', 'West Virginia Code § 48-31-106, part of the Uniform Deployed Parents Custody and Visitation Act (Article 31, Chapter 48), imposes a duty to notify of a change of address: an individual to whom custodial responsibility has been granted during deployment shall notify the deploying parent and any other individual with custodial responsibility of a child of any change of mailing address or residence until the grant is terminated, and shall provide notice to any court that has issued a custody or child support order concerning the child. Section 48-31-105 requires the deploying parent to notify the other parent of a pending deployment within 7 days. These provisions are specific to military deployment contexts. West Virginia does not appear to have a general standalone relocation-notice statute applicable to all custody cases (outside the deployment context) comparable to Tennessee''s § 36-6-108, Texas''s § 153.076, or Washington''s RCW 26.09.430–.440. The West Virginia address confidentiality program (W. Va. Code § 48-28A-101 et seq., administered by the Secretary of State) covers victims of domestic violence, sexual assault, or stalking — that is the ACP victim-protection program (the opposite of address disclosure). The general custody statute (W. Va. Code § 48-9-201 et seq.) addresses custody determinations under a best-interests standard but does not contain a standalone relocation-notice provision. For non-deployment custody cases, address change notification appears to flow from the court''s custody order and local rules rather than a specific statewide statute, so the verified relocation/notice statute for general cases is ''not found.''', 'verified', 'https://code.wvlegislature.gov/48-31-106', now()),
-- WY — Wyoming [verified]
  ('WY', 'Wyoming', 'Wyo. Stat. Ann. § 20-2-202(a)(iii) (Visitation – relocation notice requirement)', 'Wyoming Statute § 20-2-202(a)(iii) requires that when the court orders visitation, it shall ''require either parent who plans to change their home city or state of residence, to give written notice thirty (30) days prior to the move, both to the other parent and to the clerk of district court stating the date and destination of the move.'' This is embedded within the visitation-order provision, meaning the 30-day relocation notice is a mandatory component of any visitation order the court enters. There is no separate standalone relocation statute; the notice requirement is part of the court''s visitation-order authority under § 20-2-202. The statute explicitly provides a confidentiality provision: if a confidentiality order has been entered under W.S. 35-21-112 (domestic abuse protection order confidentiality) or any other order allowing a party to maintain confidentiality of addresses, the address shall remain confidential. This is the same § 35-21-112 (Confidentiality in court proceedings) that was initially found in the earlier ACP search — Wyoming ties address confidentiality in custody/visitation cases to domestic-abuse protection orders, not to a standalone custody-address-disclosure statute. Wyoming does not have a general initial-address-disclosure requirement for custody orders comparable to Texas § 105.006 or Wisconsin § 767.41(6)(h); the relocation notice in § 20-2-202(a)(iii) is the primary address-change disclosure mechanism. No separate statute requiring parents to exchange contact information at the outset of a custody case was found.', 'verified', 'https://law.justia.com/codes/wyoming/title-20/chapter-2/article-2/section-20-2-202/', now())
